    label: "Zweifachgeweihter Karmalleib",
    cost: 15,
    category: SpecialAbilityCategory.KarmalGeneral,
    prerequisiteText: "Leiteigenschaft der Tradition 15, Sonderfertigkeit Geweihter Karmalleib",
    requirements: [{ type: "priest", text: "Geweihter" }, { type: "leitTradition", min: 15, text: "Leiteigenschaft der Tradition 15" }, { type: "specialAbility", name: "geweihterKarmalleib", text: "Sonderfertigkeit Geweihter Karmalleib" }],
    effectText: "Die karmale Kraft im Körper des Geweihten ist so stark, dass waffenlose Angriffe mit der Kampftechnik Raufen als zweifachgeweihte Angriffe gelten. Dies bedeutet, dass Waffen- und Berührungsschaden den Aussagen von geweiht entsprechen, aber einen Bonus von +1 TP erhalten. Er ist damit in der Lage, Wesen schwerer zu verletzen, die ansonsten gegen profane Angriffe resistent (oder gar immun) sind.",
    subCategory: "allgemeine Fertigkeit",
