    requirements: [{ type: "priest", text: "Geweihter" }, { type: "specialAbility", name: "spitzerstachel", text: "Sonderfertigkeit Spitzer Stachel" }, { type: "specialAbility", name: "blutenderstich", forbidden: true, text: "keine Sonderfertigkeit Blutender Stich" }],
