    label: "Weg der:s Stabträger:in",
    cost: 5,
    category: SpecialAbilityCategory.KarmalCeremonialObject,
    prerequisiteText: "Sonderfertigkeit Tradition (Aveskirche), keine Sonderfertigkeit Glück mit dir",
